 "content": "def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    bg=max(set(x for row in grid for x in row),key=lambda x:sum(row.count(x) for row in grid))
    borders=[]
    # colored border runs identify projection axes/directions
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v!=bg and ((r in (0,h-1)) or (c in (0,w-1))): borders.append((r,c,v))
    # Each non-bg interior mark projects along its row/column toward a matching border color,
    # with 4 replacing the mark; border markers point inward along the line.
    for r in range(h):
      for c in range(w):
        v=grid[r][c]
        if v==bg: continue
        if (r,c,v) in borders: continue
        # choose nearest border run orientation: same color, prefer axis aligned to border location
        opts=[]
        for br,bc,bv in borders:
          if bv==v and (br==r or bc==c):
            dist=abs(br-r)+abs(bc-c); opts.append((dist,br,bc))
        if opts:
          _,br,bc=min(opts)
          dr=0 if br==r else (1 if br>r else -1)
          dc=0 if bc==c else (1 if bc>c else -1)
          # project away from nearest border, across row/column, mark origin 4
          out[r][c]=4
          if dr:
            for rr in range(r+dr,h if dr>0 else -1,dr):
              if grid[rr][c]==bg: out[rr][c]=v
          elif dc:
            for cc in range(c+dc,w if dc>0 else -1,dc):
              if grid[r][cc]==bg: out[r][cc]=v
    # border color markers extend inward as continuous lines when patterned with adjacent border cells
    for br,bc,v in borders:
      if br in (0,h-1):
        step=1 if br==0 else -1
        rr=br+step
        while 0<=rr<h and grid[rr][bc]==bg: out[rr][bc]=v; rr+=step
      if bc in (0,w-1):
        step=1 if bc==0 else -1
        cc=bc+step
        while 0<=cc<w and grid[br][cc]==bg: out[br][cc]=v; cc+=step
    return out

